<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/lifecycle/prospects.php';
function pq_installed():bool{return (bool)crm_query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='nd_manual_qr_settings'")->fetchColumn()&&crm_query("SELECT state FROM nd_schema_migrations WHERE version='025_manual_qr'")->fetchColumn()==='applied';}
function pq_storage():string{$dir=dirname(__DIR__).'/payment-qr-files';if(is_link($dir)||file_exists($dir)&&!is_dir($dir))crm_fail(503,'Хранилище QR недоступно.');if(!is_dir($dir)&&!mkdir($dir,0700))crm_fail(503,'Хранилище QR недоступно.');$real=realpath($dir);if($real!==realpath(dirname(__DIR__)).'/payment-qr-files')crm_fail(503,'Небезопасное хранилище QR.');if(PHP_SAPI!=='cli'){$web=realpath($_SERVER['DOCUMENT_ROOT']??'');if(!$web||$real===$web||str_starts_with($real,$web.'/'))crm_fail(503,'QR должен храниться приватно.');}return $real;}
function pq_settings(bool $lock=false):array{if(!pq_installed())return ['installed'=>false,'enabled'=>false,'version'=>0,'qr'=>null];$s=crm_query('SELECT * FROM nd_manual_qr_settings WHERE id=1'.($lock?' FOR UPDATE':''))->fetch()?:['id'=>1,'current_version_id'=>null,'enabled'=>0,'version'=>0];$s['installed']=true;$s['enabled']=(bool)$s['enabled'];$s['qr']=$s['current_version_id']?crm_query('SELECT id,mime,size_bytes,checksum,recipient_name,verified_at FROM nd_manual_qr_versions WHERE id=?',[$s['current_version_id']])->fetch():null;return $s;}
function pq_path(array $q):string{if(!preg_match('/^[a-f0-9]{64}$/D',$q['storage_key']))crm_fail(404,'QR не найден.');$file=pq_storage().'/'.$q['storage_key'];if(is_link($file)||!is_file($file)||filesize($file)!==(int)$q['size_bytes']||!hash_equals($q['checksum'],hash_file('sha256',$file)))crm_fail(404,'Исходный QR недоступен.');return $file;}
function pq_upload():array{
 $f=$_FILES['file']??null;$version=filter_var($_POST['version']??'',FILTER_VALIDATE_INT);$recipient=cc_text($_POST,'recipient_name',190);if(!is_int($version)||$version<0||!is_array($f)||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']))crm_fail(422,'Загрузите исходный файл QR и укажите имя получателя.');$size=filesize($f['tmp_name']);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$image=@getimagesize($f['tmp_name']);$ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['png','jpg','jpeg','webp'],true))crm_fail(422,'Загрузите исходное изображение PNG, JPG или WebP.');if(!$size||$size>pq_file_limit()||!in_array($mime,['image/png','image/jpeg','image/webp'],true)||!$image||$image[0]>4096||$image[1]>4096)crm_fail(422,'Нужен исходный PNG, JPG или WebP до текущего лимита, указанного в настройках, и 4096×4096. Пересоздавать QR не нужно.');$key=bin2hex(random_bytes(32));$path=pq_storage().'/'.$key;if(!move_uploaded_file($f['tmp_name'],$path))crm_fail(503,'Не удалось сохранить исходный QR.');chmod($path,0600);
 try{return crm_atomic(function()use($version,$recipient,$size,$mime,$key,$path){$s=pq_settings(true);if(!$s['installed'])crm_fail(503,'Модуль QR ещё не установлен.');if($version!==(int)$s['version'])crm_fail(409,'Настройки изменились. Обновите страницу.');if((int)crm_query('SELECT COALESCE(SUM(size_bytes),0) FROM nd_manual_qr_versions')->fetchColumn()+$size>67108864)crm_fail(422,'Квота истории QR 64 МБ исчерпана. Исходные версии не удаляются автоматически.');crm_query('INSERT INTO nd_manual_qr_versions(storage_key,mime,size_bytes,checksum,recipient_name) VALUES (?,?,?,?,?)',[$key,$mime,$size,hash_file('sha256',$path),$recipient]);$id=(int)db()->lastInsertId();crm_query('INSERT INTO nd_manual_qr_settings(id,current_version_id,enabled,version) VALUES (1,?,0,1) ON DUPLICATE KEY UPDATE current_version_id=VALUES(current_version_id),enabled=0,version=version+1',[$id]);lc_audit(['type'=>'owner','id'=>1],'payment_qr',$id,'original_qr_uploaded',null,['enabled'=>false]);return ['ok'=>true,'settings'=>pq_settings(),'original_bytes_preserved'=>true];});}catch(Throwable $e){unlink($path);throw $e;}
}
function pq_toggle(array $d):array{return crm_idempotent('payment-qr/toggle',$d,function()use($d){$s=pq_settings(true);if(!$s['qr'])crm_fail(422,'Сначала загрузите исходный QR.');crm_version($d,$s);$enabled=($d['enabled']??false)===true;if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите изменение способа оплаты.');if($enabled){if(($d['recipient_confirmed']??false)!==true||($d['checksum']??'')!==$s['qr']['checksum']||cc_text($d,'recipient_name',190)!==$s['qr']['recipient_name'])crm_fail(422,'Проверьте имя получателя в банке для этой точной версии QR.');crm_query('UPDATE nd_manual_qr_versions SET verified_at=UTC_TIMESTAMP(),verified_by=1 WHERE id=?',[$s['qr']['id']]);}crm_query('UPDATE nd_manual_qr_settings SET enabled=?,version=version+1 WHERE id=1',[$enabled?1:0]);lc_audit(['type'=>'owner','id'=>1],'payment_qr',(int)$s['qr']['id'],$enabled?'manual_qr_enabled':'manual_qr_disabled',null,['recipient_verified'=>$enabled]);return ['ok'=>true,'settings'=>pq_settings()];});}
function pq_released(array $i):bool{$s=crm_query('SELECT b.state,b.generated_hash,a.binding_id AS asset_id,a.payment_released_at FROM nd_lc_document_bindings b LEFT JOIN nd_lc_pdf_assets a ON a.binding_id=b.id WHERE b.id=?',[$i['schedule']['binding_id']])->fetch();if(!$s||$s['state']!=='AGREED'||$s['asset_id']!==null&&$s['payment_released_at']===null)return false;$snapshot=json_decode($i['snapshot'],true);return hash_equals($s['generated_hash'],$snapshot['agreement_hash']??'');}
function pq_assign_if_ready(int $invoice):void{if(!pq_installed())return;$s=pq_settings();if(!$s['enabled']||!$s['qr']||!$s['qr']['verified_at'])return;$i=crm_query('SELECT snapshot_hash FROM nd_invoices WHERE id=?',[$invoice])->fetch();if(!$i)return;crm_query('INSERT INTO nd_manual_qr_assignments(invoice_id,qr_version_id,invoice_snapshot_hash,released_by) VALUES (?,?,?,1) ON DUPLICATE KEY UPDATE qr_version_id=VALUES(qr_version_id),invoice_snapshot_hash=VALUES(invoice_snapshot_hash),released_at=UTC_TIMESTAMP()',[$invoice,$s['qr']['id'],$i['snapshot_hash']]);}
function pq_visible(array $i):array|false{if(!pq_installed()||$i['state']!=='issued'||bill_balance($i)['outstanding_minor']<1||!pq_released($i))return false;$s=pq_settings();if(!$s['enabled']||!$s['qr']||!$s['qr']['verified_at'])return false;$a=crm_query('SELECT * FROM nd_manual_qr_assignments WHERE invoice_id=?',[$i['id']])->fetch();if(!$a||(int)$a['qr_version_id']!==(int)$s['qr']['id']||!hash_equals($a['invoice_snapshot_hash'],$i['snapshot_hash']))return false;return $s['qr'];}
function pq_invoice(string $mode,int $id,bool $write=false):array{
 if($mode==='prospect'){$s=ps_session($write);$i=lc_invoice(['type'=>'owner','id'=>1],$id);if((int)$i['order_id']!==(int)$s['order_id'])crm_fail(404,'Запрос оплаты не найден.');ps_binding($s,(int)$i['schedule']['binding_id']);return ['invoice'=>$i,'actor'=>['type'=>'prospect','id'=>(int)$s['link_id'],'session'=>$s]];}
 $a=cc_actor($mode!=='owner',$write);$a['document_archive']=true;return ['invoice'=>lc_invoice($a,$id),'actor'=>$a];
}
function pq_claim_prospect(array $context,array $d):array{$i=$context['invoice'];$a=$context['actor'];if(!pq_released($i))crm_fail(409,'Указания по оплате ещё не выпущены.');$amount=bill_minor($d['amount']??null);if($amount<1)crm_fail(422,'Укажите фактически переведённую сумму.');return crm_idempotent('prospect-qr-claim:'.$a['id'],$d,function()use($i,$a,$d,$amount){$e=['invoice_id'=>(int)$i['id'],'binding_id'=>(int)$i['schedule']['binding_id'],'amount_minor'=>$amount,'paid_at'=>lc_paid_at(['paid_at'=>$d['paid_at']??'']),'payer'=>cc_text($d,'payer',190),'reference'=>cc_text($d,'reference',1000),'verified'=>false,'source'=>'manual_qr'];ps_event($a['id'],'prospect','payment_claimed',$e);return ['ok'=>true,'state'=>'PENDING_OWNER_BANK_VERIFICATION','client_access_activated'=>false];});}
function pq_csrf(array $context):string{$s=$context['actor']['session'];return hash_hmac('sha256','manual-payment:'.$context['invoice']['id'].':'.$s['token_hash'].':'.$s['expires_at'],$s['csrf_hash']);}
function pq_stream(array $q,bool $download=false):never{$path=pq_path($q);header('Content-Type: '.$q['mime']);header('X-Content-Type-Options: nosniff');$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$q['mime']];header('Content-Disposition: '.($download?'attachment':'inline').'; filename="payment-qr.'.$ext.'"');header('Content-Length: '.$q['size_bytes']);readfile($path);exit;}

function pq_ini_bytes(string $value):int{$n=(int)$value;return $n*match(strtolower(substr(trim($value),-1))){'g'=>1073741824,'m'=>1048576,'k'=>1024,default=>1};}
function pq_file_limit():int{$u=pq_ini_bytes((string)ini_get('upload_max_filesize'));$p=pq_ini_bytes((string)ini_get('post_max_size'));return min(8388608,$u>0?$u:8388608,$p>0?max(1,$p-65536):8388608);}
function pq_pending_claims():array{$items=[];foreach(crm_query("SELECT e.id,e.link_id,l.order_id,e.evidence_json FROM nd_lc_prospect_events e JOIN nd_lc_prospect_links l ON l.id=e.link_id WHERE e.action='payment_claimed' AND NOT EXISTS (SELECT 1 FROM nd_lc_prospect_events r WHERE r.action='payment_claim_reviewed' AND r.link_id=e.link_id AND JSON_UNQUOTE(JSON_EXTRACT(r.evidence_json,'$.claim_event_id'))=CAST(e.id AS CHAR)) ORDER BY e.id DESC LIMIT 100") as $r){$d=json_decode($r['evidence_json'],true);if(($d['source']??'')!=='manual_qr'||!isset($d['invoice_id']))continue;$i=lc_invoice(['type'=>'owner','id'=>1],(int)$d['invoice_id']);if((int)$i['order_id']!==(int)$r['order_id'])continue;$snap=json_decode($i['snapshot'],true);$items[]=['event_id'=>(int)$r['id'],'invoice_id'=>(int)$i['id'],'order_label'=>$snap['order']['number'].' · '.$i['number'],'amount'=>bill_decimal((int)$d['amount_minor']),'payer'=>$d['payer'],'reference'=>$d['reference'],'payments'=>crm_query("SELECT p.id,CONCAT(p.amount_minor/100,' руб. · ',p.verified_at) AS label FROM nd_payment_attempts p JOIN nd_payment_transactions t ON t.attempt_id=p.id WHERE p.invoice_id=? AND p.provider='manual_bank' ORDER BY p.id",[$i['id']])->fetchAll()];}return $items;}
function pq_review_claim(array $d):array{return crm_idempotent('manual-qr/review-claim',$d,function()use($d){$event=crm_query("SELECT * FROM nd_lc_prospect_events WHERE id=? AND action='payment_claimed'",[cc_id($d['event_id']??null)])->fetch();if(!$event)crm_fail(404,'Сообщение не найдено.');$claim=json_decode($event['evidence_json'],true);if(($claim['source']??'')!=='manual_qr'||($d['confirm']??false)!==true)crm_fail(422,'Подтвердите сопоставление сообщения с уже проверенным банковским поступлением.');$id=cc_id($d['payment_id']??null);if(!crm_query("SELECT p.id FROM nd_payment_attempts p JOIN nd_payment_transactions t ON t.attempt_id=p.id WHERE p.id=? AND p.invoice_id=? AND p.provider='manual_bank'",[$id,$claim['invoice_id']])->fetchColumn())crm_fail(409,'Сначала отдельно подтвердите фактическое поступление по банку для этого запроса.');if(!crm_query("SELECT id FROM nd_lc_prospect_events WHERE action='payment_claim_reviewed' AND link_id=? AND JSON_UNQUOTE(JSON_EXTRACT(evidence_json,'$.claim_event_id'))=?",[$event['link_id'],(string)$event['id']])->fetchColumn())ps_event((int)$event['link_id'],'owner','payment_claim_reviewed',['claim_event_id'=>(int)$event['id'],'matched_payment_id'=>$id,'reason'=>cc_text($d,'reason',2000),'new_income_created'=>false]);return ['ok'=>true,'new_income_created'=>false];});}
